import flask
from flask import request, jsonify
import psycopg2
import os
import hashlib
import hmac

app = flask.Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')
API_SECRET = os.environ.get('API_SECRET', 'default-hmac-key')

def get_db():
    return psycopg2.connect(
        host=DB_HOST, database=DB_NAME,
        user=DB_USER, password=DB_PASS
    )

def verify_request_signature(payload, signature):
    """Verify HMAC-SHA256 signature of request body"""
    expected = hmac.new(API_SECRET.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria.
    Supports filtering by department, role, and name pattern.
    Results are paginated with limit/offset.
    """
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    name_pattern = request.args.get('name', '')
    limit = request.args.get('limit', '20')
    offset = request.args.get('offset', '0')

    # Validate pagination params
    try:
        limit = min(int(limit), 100)
        offset = max(int(offset), 0)
    except ValueError:
        return jsonify({'error': 'Invalid pagination parameters'}), 400

    # Build query with filters
    conditions = []
    if department:
        conditions.append(f"department = '{department}'")
    if role:
        conditions.append(f"role = '{role}'")
    if name_pattern:
        conditions.append(f"display_name ILIKE '%{name_pattern}%'")

    where_clause = ''
    if conditions:
        where_clause = 'WHERE ' + ' AND '.join(conditions)

    query = f"SELECT id, display_name, email, department, role FROM users {where_clause} ORDER BY display_name LIMIT {limit} OFFSET {offset}"

    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute(query)
        rows = cur.fetchall()
        users = []
        for row in rows:
            users.append({
                'id': row[0],
                'display_name': row[1],
                'email': row[2],
                'department': row[3],
                'role': row[4]
            })
        cur.close()
        conn.close()
        return jsonify({'users': users, 'count': len(users)})
    except Exception as e:
        app.logger.error(f"Database error: {e}")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/v1/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID"""
    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute("SELECT id, display_name, email, department, role FROM users WHERE id = %s", (user_id,))
        row = cur.fetchone()
        cur.close()
        conn.close()
        if row:
            return jsonify({'id': row[0], 'display_name': row[1], 'email': row[2], 'department': row[3], 'role': row[4]})
        return jsonify({'error': 'Not found'}), 404
    except Exception as e:
        app.logger.error(f"Database error: {e}")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
